export function getSeoContent(slug: string): SeoContent | null {
  return SEO[slug] ?? null;
}

export function listSeoContentSlugs(): string[] {
  return Object.keys(SEO);
}

export function requireSeoContent(slug: string): SeoContent {
  const seo = getSeoContent(slug);
  if (!seo) {
    throw new Error(`Missing seo-content for ${slug}`);
  }
  return seo;
}

export default SEO;
